package org.usbworkbench;
import java.io.*;import java.util.*;
public final class UsbAnalyzerTest {
 static int checks;static void yes(boolean b,String m){if(!b)throw new AssertionError(m);checks++;}
 static class Disk implements BlockDevice{int bs=512;long blocks=131072,read,writes,sync;Map<Long,byte[]> data=new HashMap<>();public int blockSize(){return bs;}public long blockCount(){return blocks;}public void read(long at,byte[] b,int n)throws IOException{if(at<0||n%bs!=0||at>blocks||n/bs>blocks-at)throw new IOException("BOUND");read+=n;for(int i=0;i<n/bs;i++){byte[] v=data.get(at+i);if(v==null)Arrays.fill(b,i*bs,(i+1)*bs,(byte)0);else System.arraycopy(v,0,b,i*bs,bs);}}public void write(long at,byte[] b,int n){writes++;for(int i=0;i<n/bs;i++)data.put(at+i,Arrays.copyOfRange(b,i*bs,(i+1)*bs));}public void sync(){sync++;}public void close(){}void put(long at,byte[] b){for(int i=0;i<b.length/bs;i++)data.put(at+i,Arrays.copyOfRange(b,i*bs,(i+1)*bs));}}
 static String analyze(Disk d)throws Exception{long writes=d.writes,sync=d.sync;String r=new UsbAnalyzer(d,(a,b)->{}).analyze();yes(writes==d.writes&&sync==d.sync,"zero drive writes/sync");yes(d.read<=64L*1048576,"read budget");return UsbAnalyzer.render(r,false);}
 static void text(byte[] b,int p,String s){byte[] v=s.getBytes(java.nio.charset.StandardCharsets.US_ASCII);System.arraycopy(v,0,b,p,v.length);}static void le16(byte[] b,int p,int v){DiskTools.le16(b,p,v);}static void le32(byte[] b,int p,long v){DiskTools.le32(b,p,v);}
 static byte[] mbr(int type,long first,long n){byte[] b=new byte[512];b[450]=(byte)type;le32(b,454,first);le32(b,458,n);le16(b,510,0xaa55);return b;}
 public static void main(String[] args)throws Exception{
 Disk d=new Disk();String r=analyze(d);yes(r.contains("Unknown / no recognized table")&&r.contains("Unavailable")&&!r.contains("Free space: 0"),"blank not assumed empty filesystem");
 d=new Disk();d.blocks=262144;AdvancedDiskTools.format(d,"fat32","mbr","OWNED",0,(a,b)->{});d.read=0;r=analyze(d);yes(r.contains("Filesystem: FAT32")&&r.contains("Free space:")&&r.contains("Counted free clusters"),"actual formatted FAT32 allocation count");yes(r.contains("MBR")&&r.contains("2048 /"),"MBR offset");
 DiskTools.FatLayout layout=new DiskTools.FatLayout(d.blocks,0);long free=(layout.clusters-1)*layout.clusterSectors*512;yes(r.contains("Free space: "+free+" B"),"FAT32 exact known root allocation");
 d=new Disk();d.blocks=131072;AdvancedDiskTools.format(d,"fat16","mbr","OWNED",0,(a,b)->{});d.read=0;r=analyze(d);yes(r.contains("Filesystem: FAT16")&&r.contains("Counted free clusters"),"FAT16 allocation");
 d=new Disk();d.blocks=32768;AdvancedDiskTools.format(d,"fat12","mbr","OWNED",0,(a,b)->{});d.read=0;r=analyze(d);yes(r.contains("Filesystem: FAT12")&&r.contains("Free space:"),"FAT12 packed entries");
 d=new Disk();AdvancedDiskTools.format(d,"exfat","mbr","OWNED",0,(a,b)->{});d.read=0;r=analyze(d);yes(r.contains("Filesystem: exFAT")&&r.contains("active exFAT bitmap")&&!r.contains("Estimated free allocation"),"exFAT measured bitmap not percent");
 AdvancedDiskTools.ExFatLayout ex=new AdvancedDiskTools.ExFatLayout(d.blocks,0);yes(r.contains("Free space: "+((ex.clusters-(ex.root-1))*ex.spc*512)+" B"),"exFAT exact known allocation");
 d=new Disk();d.blocks=262144;AdvancedDiskTools.format(d,"fat32","gpt","OWNED",0,(a,b)->{});d.read=0;r=analyze(d);yes(r.contains("Partition table: GPT")&&r.contains("Primary GPT header and entries CRC32: OK")&&r.contains("Backup GPT header and entries CRC32: OK")&&r.contains("GPT copies agree: Yes"),"GPT headers/entries/backup");
 byte[] corrupt=d.data.get(1L);corrupt[16]^=1;d.read=0;r=analyze(d);yes(r.contains("primary GPT invalid")&&r.contains("Reading backup only")&&r.contains("Filesystem: FAT32"),"recover analysis from backup without repair");
 corrupt=d.data.get(d.blocks-1);corrupt[16]^=1;d.read=0;r=analyze(d);yes(r.contains("No verified GPT entries")&&!r.contains("Filesystem: FAT32"),"corrupt GPT does not guess partition offsets");
 d=new Disk();d.put(0,mbr(5,2048,10000));byte[] e=mbr(0x83,1,1000);e[466]=15;le32(e,470,0);d.put(2048,e);r=analyze(d);yes(r.contains("cyclic extended partition")&&r.contains("Volume / partition number: 5"),"bounded cyclic EBR");
 d=new Disk();d.put(0,mbr(7,999999,1));r=analyze(d);yes(r.contains("partition outside drive"),"partition range reject");
 d=new Disk();byte[] b=new byte[4096];le16(b,1080,0xef53);le32(b,1028,10000);le32(b,1036,4000);le32(b,1032,500);le32(b,1048,0);le32(b,1120,64);le16(b,1082,1);text(b,1144,"OWNED");d.put(0,b);r=analyze(d);yes(r.contains("Filesystem family: ext4")&&r.contains("Free space: 4096000 B")&&r.contains("excluding reserved blocks: 3584000 B"),"ext counters/reserved bounds");
 le32(b,1036,10001);d=new Disk();d.put(0,b);r=analyze(d);yes(r.contains("analysis incomplete")&&!r.contains("Free space:"),"invalid ext counters never invented");
 d=new Disk();d.bs=4096;d.blocks=10000;b=new byte[4096];text(b,3,"NTFS    ");le16(b,11,4096);b[13]=1;le32(b,40,9999);d.put(0,b);r=analyze(d);yes(r.contains("Logical sector size (bytes): 4096")&&r.contains("Filesystem: NTFS")&&r.contains("Unavailable"),"4Kn raw filesystem, no false free0");
 final Disk nd=d;long[] calls={0};String raw=new UsbAnalyzer(nd,(a,z)->{},view->{calls[0]++;try{view.write(0,new byte[4096],4096);throw new AssertionError();}catch(IOException expected){yes(expected.getMessage().equals("READ_ONLY"),"native provider view write denied");}return new UsbAnalyzer.Space(40960000,123456,"OWNED",0);}).analyze();yes(calls[0]==1&&UsbAnalyzer.render(raw,false).contains("Free space: 123456 B"),"NTFS space provider integrated");yes(!UsbAnalyzer.render(raw,false).matches("(?s).*[\\u0600-\\u06ff].*"),"English selected report");yes(UsbAnalyzer.render(raw,true).contains("المساحة الحرة")&&!UsbAnalyzer.render(raw,true).contains("Free space"),"Arabic selected report");
 String safe=UsbAnalyzer.clean("a\tb\nc\u202ed");yes(safe.equals("abcd"),"untrusted report control characters sanitized");
 try{new UsbAnalyzer(nd,(a,z)->{throw new IOException("CANCELLED");}).analyze();throw new AssertionError();}catch(IOException expected){yes(expected.getMessage().equals("CANCELLED"),"cancellation propagates");}
 d=new Disk();d.blocks=1;r=analyze(d);yes(r.contains("Reported drive capacity: 512 B"),"tiny drive bounded");
 d=new Disk();d.blocks=0x7fffffffL;b=new byte[512];b[0]=(byte)0xeb;text(b,3,"MSDOS5.0");le16(b,11,512);b[13]=8;le16(b,14,32);b[16]=1;le32(b,32,d.blocks);le32(b,36,2097152);le16(b,510,0xaa55);d.put(0,b);r=analyze(d);yes(r.contains("Allocation scan exceeds")&&r.contains("Unavailable")&&!r.contains("Free space:"),"large FAT scan capped, unknown not zero");
 d=new Disk();b=mbr(7,2048,1000);b[466]=7;le32(b,470,2500);le32(b,474,1000);d.put(0,b);r=analyze(d);yes(r.contains("overlapping partitions"),"overlap warning, no misleading summed totals");
 Disk unreadable=new Disk(){public void read(long at,byte[] data,int n)throws IOException{throw new IOException("OWNED_FAULT");}};r=analyze(unreadable);yes(r.contains("Disk layout analysis incomplete")&&r.contains("Reported drive capacity")&&!r.contains("Free space:"),"read fault preserves known capacity report");
 d=new Disk();d.bs=4096;d.blocks=10000;b=new byte[4096];text(b,3,"NTFS    ");le16(b,11,4096);b[13]=1;le32(b,40,9999);d.put(0,b);final Disk budget=d;long[] attempted={0};raw=new UsbAnalyzer(budget,(a,z)->{},view->{byte[] chunk=new byte[1048576];for(int i=0;i<100;i++){view.read(0,chunk,chunk.length);attempted[0]++;}throw new AssertionError();}).analyze();yes(attempted[0]<64&&budget.read<=64L*1048576&&UsbAnalyzer.render(raw,false).contains("analysis incomplete"),"native provider shares hard global read budget");
 long[] failedBytes={0};Disk failures=new Disk(){public void read(long at,byte[] data,int n)throws IOException{if(at>=8){failedBytes[0]+=n;throw new IOException("OWNED_IO");}super.read(at,data,n);}};b=new byte[512];text(b,3,"NTFS    ");le16(b,11,512);b[13]=8;le32(b,40,failures.blocks-1);failures.put(0,b);raw=new UsbAnalyzer(failures,(a,z)->{},view->{byte[] chunk=new byte[1048576];for(int i=0;i<100;i++)try{view.read(8,chunk,chunk.length);}catch(IOException expected){}return new UsbAnalyzer.Space(33554432,16777216,"OWNED",0);}).analyze();yes(failedBytes[0]>0&&failedBytes[0]+failures.read<=64L*1048576,"failed hardware requests consume read budget");yes(UsbAnalyzer.render(raw,false).contains("includes failed requests"),"report labels attempted bytes honestly");
 System.out.println("PASS: "+checks+" analyzer geometry/MBR/EBR/GPT/CRC/backup/FAT/exFAT/ext/NTFS provider/localization/bounds/cancel/zero-write checks");
 }
}
